ALTER TABLE forum_comments ADD COLUMN parent_id CHAR(36) NULL, ADD COLUMN reply_to_user_id CHAR(36) NULL, ADD COLUMN is_reply BOOLEAN NOT NULL DEFAULT FALSE, ADD CONSTRAINT comment_parent FOREIGN KEY(parent_id) REFERENCES forum_comments(id) ON DELETE SET NULL, ADD CONSTRAINT comment_reply_user FOREIGN KEY(reply_to_user_id) REFERENCES users(id) ON DELETE SET NULL;
ALTER TABLE notifications MODIFY COLUMN kind ENUM('comment','like','reply') NOT NULL;
DROP TRIGGER IF EXISTS notify_forum_comment;
CREATE TRIGGER notify_forum_comment AFTER INSERT ON forum_comments FOR EACH ROW INSERT INTO notifications(id,recipient_id,actor_id,topic_id,comment_id,kind) SELECT UUID(),t.user_id,NEW.user_id,NEW.topic_id,NEW.id,IF(NEW.reply_to_user_id=t.user_id,'reply','comment') FROM forum_topics t WHERE t.id=NEW.topic_id AND t.user_id<>NEW.user_id UNION ALL SELECT UUID(),NEW.reply_to_user_id,NEW.user_id,NEW.topic_id,NEW.id,'reply' FROM forum_topics t WHERE t.id=NEW.topic_id AND NEW.reply_to_user_id IS NOT NULL AND NEW.reply_to_user_id<>NEW.user_id AND NEW.reply_to_user_id<>t.user_id;
